type Cmd =
  | { kind: "add"; n: number }
  | { kind: "sub"; n: number }
  | { kind: "reset" };

function apply(acc: number, c: Cmd): number {
  switch (c.kind) {
    case "add":
      return acc + c.n;
    case "sub":
      return acc - c.n;
    case "reset":
      return 0;
    default: {
      const exhaustive: never = c;
      throw new Error("未知のコマンドです: " + JSON.stringify(exhaustive));
    }
  }
}

