type Item = { name: string; price: number };

function isItem(x: unknown): x is Item {
  if (typeof x !== "object" || x === null) {
    return false;
  }
  const o = x as { name?: unknown; price?: unknown };
  return typeof o.name === "string" && typeof o.price === "number";
}

function totalPrice(xs: unknown[]): number {
  let sum = 0;
  for (const x of xs) {
    if (isItem(x)) {
      sum += x.price;
    }
  }
  return sum;
}

