type Shape =
  | { kind: "circle"; radius: number }
  | { kind: "rect"; width: number; height: number }
  | { kind: "triangle"; base: number; height: number };

function area(s: Shape): number {
  switch (s.kind) {
    case "circle":
      return Math.PI * s.radius * s.radius;
    case "rect":
      return s.width * s.height;
    case "triangle":
      return (s.base * s.height) / 2;
    default: {
      const exhaustive: never = s;
      throw new Error("未知の図形です: " + JSON.stringify(exhaustive));
    }
  }
}

description_md:
年齢の文字列を検証する関数 `parseAge` を書きます。戻り値の型 `ParseOutcome` を
`ok` フラグで分かれる判別可能ユニオンとして定義してください。

```typescript
成功: { ok: true;  value: number }
失敗: { ok: false; message: string }
```

判定ルールは次の通りです。

- 整数として解釈できなければ失敗 (空文字列も失敗)
- `0` 未満または `150` より大きければ失敗
- それ以外は成功で、数値を `value` に入れる

```typescript
parseAge("42")   // => { ok: true, value: 42 }
parseAge("abc")  // => { ok: false, message: ... }
parseAge("-1")   // => { ok: false, message: ... }
```

失敗時のメッセージ本文は自由ですが、**空文字列にはしない** でください。

