type ParseOutcome =
  | { ok: true; value: number }
  | { ok: false; message: string };

function parseAge(input: string): ParseOutcome {
  const trimmed = input.trim();
  const n = Number(trimmed);
  if (trimmed === "" || !Number.isInteger(n)) {
    return { ok: false, message: "整数として解釈できません: " + input };
  }
  if (n < 0 || n > 150) {
    return { ok: false, message: "0〜150 の範囲外です: " + n };
  }
  return { ok: true, value: n };
}

