answer_code:
function summarize(x: unknown): string {
  if (x === null) {
    return "null";
  }
  if (typeof x === "number") {
    return "number:" + x;
  }
  if (typeof x === "string") {
    return "string:" + x;
  }
  if (typeof x === "object" && "x" in x && "y" in x) {
    const px = x.x;
    const py = x.y;
    if (typeof px === "number" && typeof py === "number") {
      return "point:" + px + "," + py;
    }
  }
  return "other";
}

