answer_code:
type Counts = { [key: string]: number };

function countWords(words: string[]): Counts {
  const counts: Counts = {};
  for (const word of words) {
    const current = counts[word];
    counts[word] = current === undefined ? 1 : current + 1;
  }
  return counts;
}

function countOf(counts: Counts, word: string): number {
  const value = counts[word];
  return value === undefined ? 0 : value;
}

