function union(a: number[], b: number[]): number[] {
  return [...new Set([...a, ...b])];
}

function intersection(a: number[], b: number[]): number[] {
  const inB = new Set(b);
  return [...new Set(a)].filter((x) => inB.has(x));
}

function difference(a: number[], b: number[]): number[] {
  const inB = new Set(b);
  return [...new Set(a)].filter((x) => !inB.has(x));
}

