answer_code:
function partition<T>(items: T[], pred: (item: T) => boolean): [T[], T[]] {
  const matched: T[] = [];
  const rest: T[] = [];
  for (const item of items) {
    if (pred(item)) {
      matched.push(item);
    } else {
      rest.push(item);
    }
  }
  return [matched, rest];
}

