answer_code:
function maxBy<T>(items: T[], score: (item: T) => number): T | null {
  if (items.length === 0) {
    return null;
  }
  let best = items[0];
  let bestScore = score(best);
  for (let i = 1; i < items.length; i++) {
    const currentScore = score(items[i]);
    if (currentScore > bestScore) {
      best = items[i];
      bestScore = currentScore;
    }
  }
  return best;
}

