answer_code:
function maxWindowSum(nums: number[], k: number): number {
  if (k <= 0 || k > nums.length) {
    return 0;
  }
  let sum = 0;
  for (let i = 0; i < k; i++) {
    sum += nums[i];
  }
  let best = sum;
  for (let i = k; i < nums.length; i++) {
    sum += nums[i] - nums[i - k];
    if (sum > best) {
      best = sum;
    }
  }
  return best;
}

