type Options = { retries: number; timeoutMs: number; verbose: boolean };

const DEFAULTS: Options = { retries: 3, timeoutMs: 1000, verbose: false };

function withDefaults(given: Partial<Options>): Options {
  const merged: Options = { ...DEFAULTS };
  for (const key of Object.keys(given) as (keyof Options)[]) {
    const value = given[key];
    if (value !== undefined) {
      (merged as Record<string, unknown>)[key] = value;
    }
  }
  return merged;
}

explanation_md:
既定値のコピーを土台にして、`undefined` でない値だけを上書きします。

```typescript
function withDefaults(given: Partial<Options>): Options {
  const merged: Options = { ...DEFAULTS };
  for (const key of Object.keys(given) as (keyof Options)[]) {
    const value = given[key];
    if (value !== undefined) {
      (merged as Record<string, unknown>)[key] = value;
    }
  }
  return merged;
}
```

**なぜ `{ ...DEFAULTS, ...given }` だけでは足りないのか。** スプレッドは「キーが存在するか」で判断し、
値が `undefined` かどうかは見ません。`{ timeoutMs: undefined }` にも `timeoutMs` キーは存在するので、
合成結果の `timeoutMs` は `undefined` になります。戻り値の型は `Options` なので、型の上では
`number` のはずの場所に `undefined` が入り、後段で `timeoutMs.toFixed()` が実行時に落ちます。
「型は通っているのに実行時に `undefined`」という、いちばん厄介な壊れ方です。

`{ retries: 0 }` が正しく反映されるのも要点です。`given.retries || DEFAULTS.retries` と
書くと `0` が falsy なので `3` に化けます。判定は必ず `!== undefined` (または `??`) で行ってください。

`Object.keys(given) as (keyof Options)[]` のキャストが必要なのは、`Object.keys` の戻り値が
`string[]` と決められているからです。TypeScript のオブジェクト型は「宣言したキー以外が
実行時に入っていないこと」を保証しないため (構造的部分型では余分なキーを持つ値も代入できます)、
安全側に倒して `string[]` になっています。ここは開発者が「このオブジェクトのキーはこれで全部だ」と
知っているからキャストできる場面です。

### `Partial<T>` と `Required<T>`

`Partial<Options>` は全プロパティを `?` 付きにした型、`Required<Options>` は逆に `?` を外した型です。
どちらも標準で用意されたマップ型で、`{ [K in keyof T]?: T[K] }` のように定義されています。
「入口はゆるく、出口はきっちり」— 引数を `Partial`、戻り値を元の型にするこの形は、
設定オブジェクトを扱う関数の定番の設計です。呼び出し側は好きなキーだけ渡せて、
受け取る側は全プロパティが揃っている前提でコードを書けます。

