type Article = { title: string; body: string };
type Timestamps = { createdAt: number; updatedAt: number };

type StoredArticle = Article & Timestamps;

function touch(article: StoredArticle, now: number): StoredArticle {
  return { ...article, updatedAt: now };
}

function isStale(article: StoredArticle, now: number, maxAge: number): boolean {
  return now - article.updatedAt > maxAge;
}

