answer_code:
interface Entity {
  id: number;
}

interface Named extends Entity {
  name: string;
}

interface Product extends Named {
  price: number;
}

function label(product: Product): string {
  return "#" + product.id + " " + product.name + " ¥" + product.price;
}

function cheapest(products: Product[]): Product | null {
  if (products.length === 0) {
    return null;
  }
  let best = products[0];
  for (const product of products) {
    if (product.price < best.price) {
      best = product;
    }
  }
  return best;
}

