answer_code:
function partition<T>(values: T[], predicate: (value: T) => boolean): [T[], T[]] {
  const matched: T[] = [];
  const rest: T[] = [];
  for (const value of values) {
    if (predicate(value)) {
      matched.push(value);
    } else {
      rest.push(value);
    }
  }
  return [matched, rest];
}

