answer_code:
type Method = "get" | "post";
type Resource = "users" | "posts";

type Route = `${Method} /${Resource}`;

function route(method: Method, resource: Resource): Route {
  return `${method} /${resource}`;
}

function allRoutes(): Route[] {
  const methods: Method[] = ["get", "post"];
  const resources: Resource[] = ["users", "posts"];
  const routes: Route[] = [];
  for (const method of methods) {
    for (const resource of resources) {
      routes.push(route(method, resource));
    }
  }
  return routes;
}

