answer_code:
function runSequential<T, R>(items: T[], task: (item: T) => Promise<R>): Promise<R[]> {
  return items.reduce(
    (chain: Promise<R[]>, item: T) =>
      chain.then((results) => task(item).then((value) => results.concat([value]))),
    Promise.resolve<R[]>([])
  );
}
